    let xc = rounded_f64(xc, 124)?;
    let yb = rounded_f64(yb, 124)?;
    let bc_2 = xc * yb;
    let bc = bc_1 - bc_2;
    let xa = rounded_f64(xa, 124)?;
    let ac_1 = xa * yc;
    let ya = rounded_f64(ya, 124)?;
    let ac_2 = xc * ya;
    let ac = ac_1 - ac_2;
    let ab_1 = xa * yb;
    let ab_2 = xb * ya;
    let ab = ab_1 - ab_2;
    let wa = rounded_f64(wa, 83)?;
