    let wb = rounded_f64(wb, 83)?;
    let det_2 = wb * ac;
    let det_3 = det_1 - det_2;
    let wc = rounded_f64(wc, 83)?;
    let det_4 = wc * ab;
    let det = det_3 + det_4;
